static void Build(){var scene=SceneManager.GetActiveScene();var original=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Single(r=>r.name=="building_a_00_Material #163_0");if(scene.GetRootGameObjects().Any(g=>g.name=="Miami Clothing Store"))throw new Exception("Store already exists");Directory.CreateDirectory(Backup);EditorSceneManager.SaveScene(scene,Backup+"/Scene.unity",true);var bounds=original.bounds;float w=bounds.size.z,d=bounds.size.x,y=bounds.min.y;Directory.CreateDirectory(Dir);AssetDatabase.Refresh();words=JsonUtility.FromJson<Words>(File.ReadAllText("FinalEnvironmentRoadReview/MiamiClothingArt/LetterContours.json"));var mat=AssetDatabase.LoadAssetAtPath<Material>(MaterialPath);if(mat.GetFloat("_CityLegacyAtlasY")<.6f||mat.GetFloat("_CityLegacyAtlasY")>.7f)throw new Exception("Pack atlas first");if(ShaderUtil.ShaderHasError(mat.shader))throw new Exception("Shader errors");var meshes=new[]{Make(w,d,0),Make(w,d,1),Make(w,d,2)};var root=new GameObject("Miami Clothing Store");root.transform.SetPositionAndRotation(new Vector3(bounds.center.x,y,bounds.center.z),Quaternion.Euler(0,90,0));var renderers=new Renderer[3];for(int i=0;i<3;i++){var g=new GameObject("Single mesh LOD"+i);g.transform.SetParent(root.transform,false);g.AddComponent<MeshFilter>().sharedMesh=meshes[i];var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;r.lightProbeUsage=LightProbeUsage.BlendProbes;GameObjectUtility.SetStaticEditorFlags(g,StaticEditorFlags.OccludeeStatic);renderers[i]=r;}var group=root.AddComponent<LODGroup>();group.SetLODs(new[]{new LOD(.15f,new[]{renderers[0]}),new LOD(.045f,new[]{renderers[1]}),new LOD(.008f,new[]{renderers[2]})});group.RecalculateBounds();var collider=root.AddComponent<BoxCollider>();collider.center=new Vector3(0,3.75f,0);collider.size=new Vector3(w,7.5f,d);int disabled=0;foreach(var r in original.GetComponentsInChildren<Renderer>(true)){r.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(r);disabled++;}foreach(var lod in original.GetComponentsInChildren<LODGroup>(true)){lod.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(lod);}foreach(var col in original.GetComponentsInChildren<Collider>(true)){col.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(col);}var others=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>!r.transform.IsChildOf(root.transform)&&!r.transform.IsChildOf(original.transform)&&r.bounds.min.y>y+7.5f&&bounds.Contains(r.bounds.center)&&(r.name.ToLower().Contains("billboard")||r.name.ToLower().Contains("neon")||r.name=="Mobile facade accent strips")).ToArray();foreach(var r in others){r.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(r);disabled++;}PrefabUtility.SaveAsPrefabAssetAndConnect(root,Dir+"/Miami Clothing Store.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var ctrl=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{foreach(bool n in new[]{false,true}){ctrl.Apply(n);var target=new Vector3(bounds.center.x,y+3.7f,bounds.center.z);var p=new Vector3(646.44f,36.49f,319.84f);CityLightingBuilder.Capture(ctrl,Tuple.Create(p,Quaternion.LookRotation(target-p)),"Miami-Clothing-"+(n?"Night":"Day"));var close=new Vector3(bounds.max.x+25,y+4,bounds.center.z+13);CityLightingBuilder.Capture(ctrl,Tuple.Create(close,Quaternion.LookRotation(new Vector3(bounds.max.x,y+3.5f,bounds.center.z)-close)),"Miami-Clothing-Close-"+(n?"Night":"Day"));}}finally{ctrl.Apply(night);}EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/MiamiClothingBuild.txt","SUCCESS new shop at original exact footprint "+w+"x"+d+" main roof7.5, doors2.3, rail1.1, pergola9.9 world aboveground. Single combined mesh/material per active LOD, 3 LODs triangles="+string.Join(",",meshes.Select(m=>m.triangles.Length/3))+". True extruded letter fronts/side walls and crown;40 nonrepeating display source tiles; image-only interiors,2 fashion posters, structural trim, rooftop railing/pergola; no plants/public. Existing hospital material+atlas asset identities reused, existing atlas pixels preserved exactly. Gun-shop reserve and existing other facade mappings preserved. No new lights/materials/texture assets. One simple body collider, original target tower/LOD/colliders disabled (recoverable), renderer count disabled="+disabled+". Shader errors=0.");}
